def merge_ranges(ranges):
    # Remove empty ranges
    non_empty = [r for r in ranges if r[0] < r[1]]
    # Sort by start
    sorted_ranges = sorted(non_empty, key=lambda x: x[0])
    merged = []
    for r in sorted_ranges:
        if not merged:
            merged.append(r)
        else:
            last = merged[-1]
            if r[0] <= last[1]:  # overlapping or touching
                merged[-1] = (last[0], max(last[1], r[1]))
            else:
                merged.append(r)
    return merged

import heapq
def topological(edges, nodes):
    # Remove duplicate edges
    unique_edges = set()
    for e in edges:
        unique_edges.add((e[0], e[1]))
    # Build adjacency list and indegree map
    graph = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    for u, v in unique_edges:
        # Assuming u and v are present in nodes
        graph[u].append(v)
        indegree[v] += 1
    # Initialize min-heap with nodes having zero indegree
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    # If we didn't process all nodes, there is a cycle
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result

def decode_runs(text):
    if text == "":
        return ""
    i = 0
    n = len(text)
    result = []
    while i < n:
        if not text[i].isdigit():
            raise ValueError()
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if i == start:
            raise ValueError()
        count = int(text[start:i])
        if count <= 0:
            raise ValueError()
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError()
        letter = text[i]
        i += 1
        result.append(letter * count)
    return "".join(result)

from collections import OrderedDict
def lru(capacity, operations):
    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(-1)
            # puts are ignored when capacity is zero
        return results
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.move_to_end(key)
                cache[key] = value
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value
                cache.move_to_end(key)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import heapq
def shortest(graph, start, end):
    if start == end:
        return 0
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if node == end:
            return d
        if d > dist.get(node, float('inf')):
            continue
        for neighbor, weight in graph.get(node, []):
            new_dist = d + weight
            if new_dist < dist.get(neighbor, float('inf')):
                dist[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))
    return None

from collections import deque
def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    n = len(values)
    if k > n:
        return []
    result = []
    dq = deque()  # stores indices, values at these indices are decreasing
    for i in range(n):
        # Remove indices that are out of the current window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove indices whose corresponding values are less than the current value
        while dq and values[dq[-1]] < values[i]:
            dq.pop()
        dq.append(i)
        # Start recording results once the first window is complete
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

import copy
def deep_merge(left, right):
    if isinstance(left, dict) and isinstance(right, dict):
        merged = {}
        keys = set(left.keys()) | set(right.keys())
        for key in keys:
            if key in left and key in right:
                merged[key] = deep_merge(left[key], right[key])
            elif key in left:
                merged[key] = copy.deepcopy(left[key])
            else:
                merged[key] = copy.deepcopy(right[key])
        return merged
    else:
        return copy.deepcopy(right)

from collections import defaultdict
def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    result = []
    accepted = defaultdict(list)  # key -> list of timestamps of accepted events
    for t, key in events:
        lst = accepted[key]
        # Remove timestamps that are outside the window (t - window is outside)
        while lst and lst[0] <= t - window:
            lst.pop(0)
        if len(lst) < limit:
            lst.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

def json_pointer(value, pointer):
    if pointer == "":
        return value

    # Decode JSON Pointer escape sequences (~0 -> ~, ~1 -> /)
    decoded_chars = []
    i = 0
    n = len(pointer)
    while i < n:
        c = pointer[i]
        if c == '~':
            if i + 1 >= n:
                raise ValueError("Malformed escape")
            next_c = pointer[i + 1]
            if next_c == '0':
                decoded_chars.append('~')
                i += 2
            elif next_c == '1':
                decoded_chars.append('/')
                i += 2
            else:
                raise ValueError("Malformed escape")
        else:
            decoded_chars.append(c)
            i += 1
    decoded = ''.join(decoded_chars)

    # Split into segments, ignoring leading empty segment from initial '/'
    segments = decoded.split('/')
    if segments and segments[0] == '':
        segments = segments[1:]

    current = value
    for seg in segments:
        if isinstance(current, dict):
            if seg in current:
                current = current[seg]
            else:
                raise ValueError("Missing path")
        elif isinstance(current, list):
            # Validate list index: must be nonnegative decimal with no leading zeros unless zero
            if not seg.isdigit():
                raise ValueError("Invalid list index")
            if len(seg) > 1 and seg[0] == '0':
                raise ValueError("Invalid list index leading zero")
            idx = int(seg)
            if idx < 0 or idx >= len(current):
                raise ValueError("Missing path")
            current = current[idx]
        else:
            # Further navigation into a non-container is invalid
            raise ValueError("Invalid path")
    return current

def stable_unique(values):
    """Return a list of the values with duplicates removed, preserving the first occurrence."""
    result = []
    seen = []
    for v in values:
        # Check if v is equal to any previously seen value
        if not any(v == s for s in seen):
            result.append(v)
            seen.append(v)
    return result

def parse_duration(text):
    if not text:
        raise ValueError("Empty input")
    i = 0
    n = len(text)
    seen = set()
    segments = []
    unit_order = {'h': 3, 'm': 2, 's': 1}
    while i < n:
        if not text[i].isdigit():
            raise ValueError("Malformed input")
        num_start = i
        while i < n and text[i].isdigit():
            i += 1
        if i == n:
            raise ValueError("Malformed input: missing unit")
        num_str = text[num_start:i]
        if i >= n or text[i] not in 'hms':
            raise ValueError("Malformed input: expected unit")
        unit = text[i]
        i += 1
        num = int(num_str)
        if unit in seen:
            raise ValueError("Duplicate unit")
        seen.add(unit)
        segments.append((num, unit))
    prev_unit = None
    for _, unit in segments:
        if prev_unit is not None:
            if unit_order[unit] > unit_order[prev_unit]:
                raise ValueError("Units not in descending order")
        prev_unit = unit
    total = 0
    for num, unit in segments:
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError
    if after is None:
        filtered = items
    else:
        filtered = [item for item in items if item['id'] > after]
    filtered.sort(key=lambda x: x['id'])
    page = filtered[:limit]
    next_cursor = None
    if len(page) == limit and len(filtered) > limit:
        next_cursor = page[-1]['id']
    return page, next_cursor

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments are not allowed")
    delays = []
    for i in range(attempts):
        delay = initial * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays

import csv
from io import StringIO
def csv_records(text):
    if text.strip() == "":
        return []
    reader = csv.reader(StringIO(text), delimiter=',', quotechar='"')
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    # Check for duplicate headers
    if len(set(headers)) != len(headers):
        raise ValueError("Duplicate headers")
    records = []
    for row in rows[1:]:
        if len(row) != len(headers):
            raise ValueError("Row has different number of fields")
        records.append(dict(zip(headers, row)))
    return records

def version_sort(versions):
    def key_func(version):
        # Split version string by dots and convert to integers
        nums = [int(x) for x in version.split('.')]
        # Strip trailing zero segments
        while nums and nums[-1] == 0:
            nums.pop()
        return tuple(nums)
    # Stable sort preserves input order for ties
    return sorted(versions, key=key_func)

def glob_match(pattern, text):
    p = 0  # pattern index
    t = 0  # text index
    star_idx = -1  # index of last '*' in pattern
    match_idx = 0  # index in text where '*' started matching
    while t < len(text):
        if p < len(pattern) and pattern[p] == '?':
            p += 1
            t += 1
        elif p < len(pattern) and pattern[p] == '*':
            star_idx = p
            match_idx = t
            p += 1
        elif star_idx != -1:
            # backtrack: let '*' match one more character
            p = star_idx + 1
            match_idx += 1
            t = match_idx
        elif p < len(pattern) and pattern[p] == text[t]:
            p += 1
            t += 1
        else:
            return False
    # consume remaining '*' in pattern
    while p < len(pattern) and pattern[p] == '*':
        p += 1
    return p == len(pattern)

def memo_cycle(definitions, name):
    memo = {}
    def dfs(n, stack):
        if n in stack:
            raise ValueError("Cycle detected")
        if n in memo:
            return memo[n]
        if n not in definitions:
            raise ValueError("Missing dependency")
        val = definitions[n]
        if isinstance(val, int):
            memo[n] = val
            return val
        elif isinstance(val, list):
            stack.add(n)
            total = 0
            for dep in val:
                total += dfs(dep, stack)
            stack.remove(n)
            memo[n] = total
            return total
        else:
            raise ValueError("Invalid definition")
    return dfs(name, set())
